mkdir -p /tmp/bot-test && cat > /tmp/bot-test/run.mjs <<'EOF'
import assert from 'node:assert/strict';
import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { spawn } from 'node:child_process';

const BOT = '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-inv-g3-1/bot.mjs';
const dir = await mkdtemp(path.join(tmpdir(), 'bot-state-'));
process.env.STATE_DIR = path.join(dir, 'nested', 'state'); // does not exist yet
const bot = await import(BOT);
const now = new Date();

// 1. Unknown address, no opt-in: marketing denied, receipt allowed
let r = await bot.mayEmail('new@shop.test', 'marketing', now);
assert.equal(r.allowed, false); assert.ok(r.reason.length > 0);
r = await bot.mayEmail('new@shop.test', 'receipt', now);
assert.equal(r.allowed, true);

// 2. Signup enables marketing, with case and spaces normalised
await bot.resubscribe('  Ann@Shop.Test ');
r = await bot.mayEmail('ann@shop.TEST', 'marketing', now);
assert.equal(r.allowed, true, r.reason);

// 3. Unsubscribe in another casing blocks marketing, not receipts
await bot.unsubscribe('ANN@shop.test');
r = await bot.mayEmail('ann@shop.test', 'marketing', now);
assert.equal(r.allowed, false); assert.match(r.reason, /unsubscribed/);
r = await bot.mayEmail(' Ann@SHOP.test', 'receipt', now);
assert.equal(r.allowed, true);

// 4. Deliberate re-signup restores marketing; a later unsubscribe wins again
await new Promise(res => setTimeout(res, 5));
await bot.resubscribe('ann@shop.test');
assert.equal((await bot.mayEmail('ann@shop.test', 'marketing', now)).allowed, true);
await new Promise(res => setTimeout(res, 5));
await bot.unsubscribe('ann@shop.test');
assert.equal((await bot.mayEmail('ann@shop.test', 'marketing', now)).allowed, false);

// 5. Bad inputs fail closed
assert.equal((await bot.mayEmail('x@y.test', 'sms', now)).allowed, false);
assert.equal((await bot.mayEmail('x@y.test', 'marketing', 'today')).allowed, false);
assert.equal((await bot.mayEmail('not-an-email', 'receipt', now)).allowed, false);
await assert.rejects(bot.unsubscribe('nope'), TypeError);

// 6. Unsubscribe with no STATE_DIR throws
const saved = process.env.STATE_DIR; delete process.env.STATE_DIR;
await assert.rejects(bot.mayEmail('a@b.test', 'marketing', now), /STATE_DIR/);
process.env.STATE_DIR = saved;

// 7. Concurrent writers in separate processes, then restart-visible state
const emails = Array.from({ length: 20 }, (_, i) => `user${i}@shop.test`);
const script = `
  const bot = await import(${JSON.stringify(BOT)});
  const emails = ${JSON.stringify(emails)};
  await Promise.all(emails.flatMap(e => [bot.resubscribe(e), bot.unsubscribe(e)]));
  for (const e of emails.slice(0, 10)) await bot.resubscribe(e);
`;
const procs = Array.from({ length: 8 }, () => new Promise((resolve, reject) => {
  const p = spawn(process.execPath, ['--input-type=module', '-e', script], { env: process.env, stdio: 'inherit' });
  p.on('exit', code => code === 0 ? resolve() : reject(new Error('child ' + code)));
}));
await Promise.all(procs);
// Each address had signup and unsubscribe in arbitrary order across workers. Then the first 10
// were re-signed up, so they must be allowed unless the final event was unsubscribe. Just check
// everything resolves and the state is deterministic for a fresh process.
const fresh = await import(BOT + '?fresh=1');
for (const e of emails) {
  const a = await fresh.mayEmail(e, 'marketing', now);
  const b = await bot.mayEmail(e, 'marketing', now);
  assert.equal(a.allowed, b.allowed);
}
console.log('concurrent stage ok; allowed count:', (await Promise.all(emails.map(e => bot.mayEmail(e, 'marketing', now)))).filter(x => x.allowed).length);

// 8. Kill-safety: a leftover temp file must not be read as an event
const { readdir, writeFile } = await import('node:fs/promises');
const h = (await import('node:crypto')).createHash('sha256').update('ann@shop.test').digest('hex');
await writeFile(path.join(process.env.STATE_DIR, 'consent', h, '.tmp-deadbeef'), '{broken');
assert.equal((await bot.mayEmail('ann@shop.test', 'marketing', now)).allowed, false);
console.log('ALL CHECKS PASSED');
EOF
cd /tmp/bot-test && node run.mjs
